        delta_hi = int(data[index + 7])
        index += 8

        for k in range(mi):
            day = di + k * delta_di
            left = li + k * delta_xi
            right = ri + k * delta_xi
            height = hi + k * delta_hi
            fogs.append((day, left, right, height))

    fogs.sort()
    max_x = max(fog[2] for fog in fogs)
    st = SegmentTree(max_x + 1)

    missed_fogs = 0
    current_day = 0
    fog_index = 0
    fog_count = len(fogs)

    while fog_index < fog_count:
        if fogs[fog_index][0] > current_day:
            # Calculate missed fogs for the current day
            for x in range(max_x + 1):
